/// <summary>
///     The <c>AVAAVACBSCommissSplitCreateFrm_Extension</c> class is the extension for <c>AVACBSCommissSplitCreate</c>
/// </summary>
[ExtensionOf(formStr(AVACBSCommissSplitCreate))]
final class AVAAVACBSCommissSplitCreateFrm_Extension
{
    // globals
    public CommissSalesGroup        frmCommissSalesGroup;
    public AVACBSConditionModeID    frmAVACBSConditionModeID;
    public AVACBSCommissSplit       frmAVACBSCommissSplit;
    public AVACBSCalcRate           frmAVACBSCalcRate;
    // form controls
    public FormStringControl        frmFSCCommissSalesGroup;
    public FormStringControl        frmFSCAVACBSConditionModeID;
    public FormRealControl          frmFRCAVACBSCommissSplit;
    public FormRealControl          frmFRCAVACBSCalcRate;

}

Method.Source:
/// <summary>
///     AVA <c>init</c> method.
///     AVA - Schneider 03.06.2024
/// </summary>
public void init()
{
    next init();

    this.avaInitFormValues();
}

/// <summary>
///     AVA <c>avaInitFormValues</c> method.
///     AVA - Schneider 03.06.2024
/// </summary>
public void avaInitFormValues()
{
    AVACBSCommissSplitForm          locAVACBSCommissSplitForm;
    KCS_BOSCentrLocatCommissSplit   locKCS_BOSCentrLocatCommissSplit;

    locAVACBSCommissSplitForm           = commissSplitForm;
    locKCS_BOSCentrLocatCommissSplit    = commissSplitForm.parmSourceSplitTable();

    //this.design().
    frmFSCCommissSalesGroup     = CommissSalesGroup;
    this.editAVACommissSalesGroup(true, locKCS_BOSCentrLocatCommissSplit.SalesGroup);
    frmFSCCommissSalesGroup.text(commissSplitForm.parmAVACommissSalesGroup());

    frmFSCAVACBSConditionModeID = AVACBSConditionModeID;
    this.editAVAConditionModeID(true, locKCS_BOSCentrLocatCommissSplit.ConditionModeID);
    frmFSCAVACBSConditionModeID.text(commissSplitForm.parmAVACBSConditionModeID());

    frmFRCAVACBSCommissSplit    = AVACBSCommissSplit;
    this.editAVACommissSplit(true, locKCS_BOSCentrLocatCommissSplit.CommissSplit);
    frmFRCAVACBSCommissSplit.realValue(commissSplitForm.parmAVACommissSplit());

    frmFRCAVACBSCalcRate        = AVACBSCalcRate;
    this.editAVACalcRate(true, locKCS_BOSCentrLocatCommissSplit.CommissionRate);
    frmFRCAVACBSCalcRate.realValue(commissSplitForm.parmAVACalcRate());
}

/// <summary>
///     AVA <c>parmAVACommissSalesGroup</c> method.
///     AVA - Schneider 03.06.2024
/// </summary>
/// <param name="_parmValue">
///     <c>CommissSalesGroup</c> as type
/// </param>
/// <returns>
///     <c>CommissSalesGroup</c> as return value
/// </returns>
public CommissSalesGroup parmAVACommissSalesGroup(CommissSalesGroup _parmValue = frmCommissSalesGroup)
{
    frmCommissSalesGroup = _parmValue;

    return frmCommissSalesGroup;
}

