///     <c>CommissSalesGroup</c> as return value
/// </returns>
edit CommissSalesGroup editAVACommissSalesGroup(boolean _set, CommissSalesGroup _paraValue)
{
    if (_set)
    {
        commissSplitForm.parmAVACommissSalesGroup(_paraValue);
    }

    return commissSplitForm.parmAVACommissSalesGroup();
}

